import { useState } from "react";

export function SelectableCard({
  title = "{{title}}",
  body = "{{body}}",
  selected: initialSelected = {{selected}},
  color = "{{color}}",
}) {
  const [selected, setSelected] = useState(initialSelected);
  return (
    <label style={{ display: "block", font: "14px system-ui, sans-serif", color: "#241430", maxWidth: 260, cursor: "pointer" }}>
      <input type="checkbox" checked={selected} onChange={() => setSelected((v) => !v)} style={{ position: "absolute", opacity: 0, width: 1, height: 1 }} />
      <span style={{
        display: "flex", gap: 10, alignItems: "flex-start", borderRadius: 10, padding: 14,
        border: "1.5px solid " + (selected ? color : "#24143022"),
        background: selected ? color + "29" : "transparent",
      }}>
        <span style={{
          width: 18, height: 18, borderRadius: 5, flex: "none", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 12,
          border: "1.5px solid " + (selected ? color : "#24143033"),
          background: selected ? color : "transparent", color: selected ? "#241430" : "transparent",
        }}>✓</span>
        <span>
          <strong style={{ display: "block" }}>{title}</strong>
          <span style={{ display: "block", fontSize: 12, opacity: 0.75 }}>{body}</span>
        </span>
      </span>
    </label>
  );
}
